function ordAt(cx,cy){ var t;
  if(_ordDir){ var nx=(cx-DW*0.5)/DW, ny=(cy-DH*0.5)/DH;
    t=0.5-(nx*_ordDir.x+ny*_ordDir.y)*1.18; }   // ramp across a direction
  else { var dxn=(cx-DW*0.5)/(DW*0.5), dyn=(cy-DH*0.5)/(DH*0.5);
    t=1-clamp(Math.hypot(dxn,dyn)/1.35,0,1); }  // radial
  t+=(_noise(cx/230,cy/230)-0.5)*0.42;  // organic wobble on the boundary
  return clamp(t,0,1);
}
function stateFor(ord){
  var tHi=1-_res, band=0.2;
  if(ord>=tHi) return 'paint';
  if(ord>=tHi-band) return 'glaze';
  return 'drawn';
}
